using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
public static class BuildAuthoredForestRoute
{
 const string Folder="Assets/Game/Generated/AuthoredLongForest";
 const float Start=-88,End=-42,Width=100;
 struct V{public Vector3 p,n;public Vector2 uv;public Vector4 root;public V Mix(V b,float t)=>new V{p=Vector3.Lerp(p,b.p,t),n=Vector3.Lerp(n,b.n,t).normalized,uv=Vector2.Lerp(uv,b.uv,t),root=Vector4.Lerp(root,b.root,t)};}
 static GameObject forest;static MeshCollider road;static HashSet<Collider> originalGround;
 static float[] roadZ,roadY;static Dictionary<Vector2Int,float> heightCache=new Dictionary<Vector2Int,float>();static Dictionary<Material,Material> materials=new Dictionary<Material,Material>();
 static float At(float[] values,float x){float u=Mathf.Clamp(x-Start,0,values.Length-1);int i=Mathf.Min(values.Length-2,Mathf.FloorToInt(u));return Mathf.Lerp(values[i],values[i+1],u-i);}
 static float H(float x,float z){var key=new Vector2Int(Mathf.RoundToInt(x*2),Mathf.RoundToInt(z*2));if(heightCache.TryGetValue(key,out float y))return y;var hits=Physics.RaycastAll(new Vector3(key.x*.5f,150,key.y*.5f),Vector3.down,350,~0,QueryTriggerInteraction.Ignore).Where(h=>originalGround.Contains(h.collider)).OrderBy(h=>h.distance).ToArray();y=hits.Length>0?hits[0].point.y:At(roadY,x)-12;heightCache[key]=y;return y;}
 static List<V> Clip(List<V> input,Func<Vector3,float> distance){var output=new List<V>();if(input.Count==0)return output;V a=input[input.Count-1];float da=distance(a.p);foreach(var b in input){float db=distance(b.p);if((da<=0)!=(db<=0))output.Add(a.Mix(b,da/(da-db)));if(db<=0)output.Add(b);a=b;da=db;}return output;}
 static List<List<V>> TrimEnd(List<V> polygon,Vector3 end,Vector3 forward){var right=Vector3.Cross(Vector3.up,forward);return new List<List<V>>{Clip(polygon,p=>Vector3.Dot(p-end,forward)),Clip(Clip(polygon,p=>-Vector3.Dot(p-end,forward)),p=>Vector3.Dot(p-end,right)+Width),Clip(Clip(polygon,p=>-Vector3.Dot(p-end,forward)),p=>Width-Vector3.Dot(p-end,right))}.Where(p=>p.Count>=3).ToList();}
 static Mesh SaveMesh(Mesh mesh,string path){var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old==null){AssetDatabase.CreateAsset(mesh,path);return mesh;}EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);EditorUtility.SetDirty(old);return old;}
 static bool Ground(string name)=>name.Contains("Terrain_Far")||name.Contains("Aerial_Grass")||name.Contains("Ground_Dirt")||name.Contains("Dirt_Road")||name.Contains("Road_Edge")||name.Contains("Grass_Close")||name.Contains("Sloped_Rock")||name.Contains("Tall_Cliff")||name.Contains("Cobblestone")||name.Contains("Mud_Pile");
 static bool Rigid(string name)=>name.Contains("Tree_Atlas")||name.Contains("Trunk")||name.Contains("Bush");
 static Material Mat(Material original){if(materials.TryGetValue(original,out var m))return m;m=new Material(original);m.name="Authored module "+original.name;m.SetFloat("_LocalWindAnchor",1);AssetDatabase.CreateAsset(m,Folder+"/"+m.name+".mat");materials[original]=m;return m;}
 static Vector3 Root(Vector4 a)=>new Vector3(a.x,a.z,a.y);
 static Vector3[] Center(int turn,int direction){int count=(int)(End-Start)+1;var points=new Vector3[count];for(int i=1;i<count;i++){float t=(i-.5f)/(count-1);float yaw=(turn*25*Mathf.SmoothStep(0,1,t)+12*Mathf.Sin(t*Mathf.PI*2))*Mathf.Deg2Rad;points[i]=points[i-1]+new Vector3(Mathf.Sin(yaw),0,Mathf.Cos(yaw));}for(int i=0;i<count;i++)points[i].y=direction*4.6f*Mathf.SmoothStep(0,1,i/(float)(count-1));return points;}
 static Vector3 On(Vector3[] center,float x){float s=Mathf.Clamp(x-Start,0,center.Length-1);int i=Mathf.Min(center.Length-2,Mathf.FloorToInt(s));return Vector3.Lerp(center[i],center[i+1],s-i);}
 static Vector3 Forward(Vector3[] center,float x){var p=On(center,Mathf.Min(End,x+.3f))-On(center,Mathf.Max(Start,x-.3f));p.y=0;return p.normalized;}
 static Vector3 Map(Vector3 p,Vector3[] center,Vector3 seam,float[] seamHeights)
 {
  float x=Mathf.Clamp(p.x,Start,End),cross=-(p.z-At(roadZ,x));var mid=On(center,x);var right=Vector3.Cross(Vector3.up,Forward(center,x));float originalOffset=p.y-At(roadY,x),edge=Mathf.Min(x-Start,End-x);float blend=1-Mathf.SmoothStep(0,1,Mathf.Clamp01(edge/9));
  float f=Mathf.Clamp(cross+Width,0,seamHeights.Length-1);int n=Mathf.Min(seamHeights.Length-2,Mathf.FloorToInt(f));float seamOffset=Mathf.Lerp(seamHeights[n],seamHeights[n+1],f-n)+(p.y-H(x,p.z));float y=Mathf.Lerp(originalOffset,seamOffset,blend);
  return mid+right*cross+Vector3.up*y;
 }
 static GameObject Module(int family,int turn,int direction,Vector3 seam,float[] seamHeights)
 {
  string id="Family "+family+" bend "+turn+" height "+direction;var root=new GameObject(id);var descriptor=root.AddComponent<AuthoredForestBlock>();var center=Center(turn,direction);descriptor.road=center;descriptor.distance=new float[center.Length];for(int i=1;i<center.Length;i++)descriptor.distance[i]=descriptor.distance[i-1]+Vector3.Distance(center[i],center[i-1]);descriptor.length=descriptor.distance.Last();descriptor.exit=center.Last();descriptor.exitYaw=turn*25;
  foreach(var f in forest.GetComponentsInChildren<MeshFilter>())
  {
   var source=f.sharedMesh;var positions=source.vertices;var normals=source.normals;var uv=source.uv;var anchors=new List<Vector4>();source.GetUVs(2,anchors);bool hasRoots=anchors.Count==positions.Length;var originalMaterial=f.GetComponent<Renderer>().sharedMaterial;bool rigid=Rigid(originalMaterial.name)&&hasRoots,ground=Ground(originalMaterial.name);var output=new List<V>();var triangles=new List<int>();var index=source.triangles;var rootMap=new Dictionary<Vector4,(Vector3,Quaternion)>();
   for(int j=0;j<index.Length;j+=3)
   {
    var polygon=new List<V>();for(int k=0;k<3;k++){int n=index[j+k];polygon.Add(new V{p=f.transform.TransformPoint(positions[n]),n=f.transform.TransformDirection(normals[n]),uv=uv.Length==positions.Length?uv[n]:Vector2.zero,root=hasRoots?anchors[n]:Vector4.zero});}
    if(rigid){var a=Root(polygon[0].root);float cross=-(a.z-At(roadZ,a.x));if(a.x<Start||a.x>=End||Mathf.Abs(cross)>Width-3)continue;}
    else{polygon=Clip(polygon,p=>Start-p.x);polygon=Clip(polygon,p=>p.x-End);polygon=Clip(polygon,p=>p.z-At(roadZ,p.x)-Width);polygon=Clip(polygon,p=>At(roadZ,p.x)-p.z-Width);}
    if(polygon.Count<3)continue;int begin=output.Count;
    foreach(var vertex in polygon){var v=vertex;if(rigid){if(!rootMap.TryGetValue(v.root,out var mapped)){var a=Root(v.root);mapped=(Map(a,center,seam,seamHeights),Quaternion.FromToRotation(Vector3.right,Forward(center,a.x)));rootMap[v.root]=mapped;}v.p=mapped.Item1+mapped.Item2*(v.p-Root(v.root));v.n=mapped.Item2*v.n;v.root=new Vector4(mapped.Item1.x,mapped.Item1.z,mapped.Item1.y,1);}else{var a=hasRoots?Map(Root(v.root),center,seam,seamHeights):Vector3.zero;v.p=Map(v.p,center,seam,seamHeights);v.n=Quaternion.FromToRotation(Vector3.right,Forward(center,vertex.p.x))*v.n;v.root=new Vector4(a.x,a.z,a.y,1);}output.Add(v);}
    for(int k=1;k<polygon.Count-1;k++)triangles.AddRange(new[]{begin,begin+k,begin+k+1});
   }
   if(output.Count==0)continue;var mesh=new Mesh{name=id+" "+f.name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(output.Select(v=>v.p).ToList());mesh.SetNormals(output.Select(v=>v.n).ToList());mesh.SetUVs(0,output.Select(v=>v.uv).ToList());mesh.SetUVs(2,output.Select(v=>v.root).ToList());mesh.SetTriangles(triangles,0);if(ground)mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Folder+"/"+mesh.name+".asset");var go=new GameObject(f.name);go.transform.SetParent(root.transform,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=Mat(originalMaterial);
   if(ground||originalMaterial.name.Contains("Trunk")||originalMaterial.name.Contains("Fence")||originalMaterial.name.Contains("Wood_Log")){go.AddComponent<MeshCollider>().sharedMesh=mesh;if(ground){var cover=go.AddComponent<ForestGroundPatch>();cover.fallbackCover=originalMaterial.name.Contains("Grass")||originalMaterial.name.Contains("Terrain_Far")?1:0;}}
  }
  var prefab=PrefabUtility.SaveAsPrefabAsset(root,Folder+"/"+id+".prefab");UnityEngine.Object.DestroyImmediate(root);return prefab;
 }
 static void CropMesh(MeshFilter f,MeshCollider collider,Vector3 low,Vector3 lowDir,Vector3 high,Vector3 highDir,string id)
 {
  var original=f!=null?f.sharedMesh:collider.sharedMesh;if(original==null)return;var transform=f!=null?f.transform:collider.transform;var p=original.vertices;var n=original.normals;var uv=original.uv;var roots=new List<Vector4>();original.GetUVs(2,roots);bool attributes=f!=null,hasRoots=roots.Count==p.Length;var output=new List<V>();var triangles=new List<int>();var t=original.triangles;bool rigid=f!=null&&Rigid(f.GetComponent<Renderer>().sharedMaterial.name)&&hasRoots;
  for(int j=0;j<t.Length;j+=3){var polygon=new List<V>();for(int k=0;k<3;k++){int i=t[j+k];polygon.Add(new V{p=transform.TransformPoint(p[i]),n=n.Length==p.Length?transform.TransformDirection(n[i]):Vector3.up,uv=uv.Length==p.Length?uv[i]:Vector2.zero,root=hasRoots?roots[i]:Vector4.zero});}var polygons=new List<List<V>>{polygon};if(rigid){var a=Root(polygon[0].root);if(Vector3.Dot(a-low,lowDir)>0&&Mathf.Abs(Vector3.Dot(a-low,Vector3.Cross(Vector3.up,lowDir)))<Width||Vector3.Dot(a-high,highDir)>0&&Mathf.Abs(Vector3.Dot(a-high,Vector3.Cross(Vector3.up,highDir)))<Width)continue;}else{polygons=polygons.SelectMany(v=>TrimEnd(v,low,lowDir)).ToList();polygons=polygons.SelectMany(v=>TrimEnd(v,high,highDir)).ToList();}foreach(var poly in polygons){if(poly.Count<3)continue;int start=output.Count;foreach(var v in poly){var a=v;a.p=transform.InverseTransformPoint(v.p);a.n=transform.InverseTransformDirection(v.n);output.Add(a);}for(int k=1;k<poly.Count-1;k++)triangles.AddRange(new[]{start,start+k,start+k+1});}}
  if(triangles.Count==0){if(f!=null)f.GetComponent<Renderer>().enabled=false;if(collider!=null)collider.enabled=false;return;}var mesh=new Mesh{name="Main join "+id,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(output.Select(v=>v.p).ToList());mesh.SetTriangles(triangles,0);if(attributes){mesh.SetNormals(output.Select(v=>v.n).ToList());mesh.SetUVs(0,output.Select(v=>v.uv).ToList());if(hasRoots)mesh.SetUVs(2,output.Select(v=>v.root).ToList());mesh.RecalculateTangents();}mesh.RecalculateBounds();mesh=SaveMesh(mesh,Folder+"/Main join "+id+".asset");if(f!=null){f.sharedMesh=mesh;PrefabUtility.RecordPrefabInstancePropertyModifications(f);}if(collider!=null){collider.sharedMesh=mesh;PrefabUtility.RecordPrefabInstancePropertyModifications(collider);}
 }
 static string RepairCurrentJoins(){var scene=SceneManager.GetActiveScene();var route=UnityEngine.Object.FindAnyObjectByType<AuthoredForestRoute>();forest=scene.GetRootGameObjects().First(g=>g.name=="Forest - imported dirt road environment");var collision=scene.GetRootGameObjects().First(g=>g.name=="Forest solid collision - visible surface");var backup=EditorSceneManager.OpenScene("Assets/Game/Scenes/BeforeAuthoredLongForest.unity",OpenSceneMode.Additive);try{var original=backup.GetRootGameObjects().First(g=>g.name==forest.name).GetComponentsInChildren<MeshFilter>(true).ToDictionary(f=>f.name);foreach(var f in forest.GetComponentsInChildren<MeshFilter>(true)){f.sharedMesh=original[f.name].sharedMesh;f.GetComponent<Renderer>().enabled=original[f.name].GetComponent<Renderer>().enabled;if(f.TryGetComponent<MeshCollider>(out var c)&&original[f.name].TryGetComponent<MeshCollider>(out var o)){c.sharedMesh=o.sharedMesh;c.enabled=o.enabled;}}var colliders=backup.GetRootGameObjects().First(g=>g.name==collision.name).GetComponentsInChildren<MeshCollider>(true).ToDictionary(c=>c.name);foreach(var c in collision.GetComponentsInChildren<MeshCollider>(true)){c.sharedMesh=colliders[c.name].sharedMesh;c.enabled=colliders[c.name].enabled;}}finally{EditorSceneManager.CloseScene(backup,true);SceneManager.SetActiveScene(scene);}var a=route.arms[0];var b=route.arms[1];var da=Quaternion.Euler(0,a.yaw,0)*Vector3.forward;var db=Quaternion.Euler(0,b.yaw,0)*Vector3.forward;foreach(var f in forest.GetComponentsInChildren<MeshFilter>(true))CropMesh(f,f.GetComponent<MeshCollider>(),a.entrance,da,b.entrance,db,f.name);int i=0;foreach(var c in collision.GetComponentsInChildren<MeshCollider>(true))CropMesh(null,c,a.entrance,da,b.entrance,db,"collision "+i++);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return "Repaired joins with local 200m-wide end corridors; original road loops outside the joining corridors retained.";}
 public static string Main(){if(Application.isPlaying)throw new Exception("Stop Play first");if(UnityEngine.Object.FindAnyObjectByType<AuthoredForestRoute>()!=null)return RepairCurrentJoins();var scene=SceneManager.GetActiveScene();string backup="Assets/Game/Scenes/BeforeAuthoredLongForest.unity";if(File.Exists(backup))throw new Exception("Backup exists; inspect partial state");EditorSceneManager.SaveScene(scene,backup,true);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();forest=GameObject.Find("Forest - imported dirt road environment");road=forest.GetComponentsInChildren<MeshFilter>().First(f=>f.name.EndsWith(".025")).GetComponent<MeshCollider>();originalGround=new HashSet<Collider>(forest.GetComponentsInChildren<MeshCollider>().Where(c=>c.GetComponent<Renderer>()!=null&&Ground(c.GetComponent<Renderer>().sharedMaterial.name)));Physics.SyncTransforms();
  int count=(int)(End-Start)+1;roadZ=new float[count];roadY=new float[count];for(int i=0;i<count;i++){float x=Start+i;var hits=new List<RaycastHit>();for(float z=-70;z<85;z+=.5f)if(road.Raycast(new Ray(new Vector3(x,100,z),Vector3.down),out var h,200))hits.Add(h);float top=hits.Max(h=>h.point.y);var upper=hits.Where(h=>h.point.y>top-1.2f).ToArray();roadZ[i]=upper.Average(h=>h.point.z);if(!road.Raycast(new Ray(new Vector3(x,100,roadZ[i]),Vector3.down),out var center,200))center=upper[upper.Length/2];roadY[i]=center.point.y;}
  var endpoints=new[]{new Vector3(128,3.3f,-39),new Vector3(-94,36.26f,28)};var directions=new[]{new Vector3(1,0,1).normalized,new Vector3(-1,0,-.15f).normalized};var arms=new AuthoredForestArm[2];
  for(int family=0;family<2;family++){var p=endpoints[family];if(road.Raycast(new Ray(p+Vector3.up*20,Vector3.down),out var hit,50))p.y=hit.point.y;endpoints[family]=p;var right=Vector3.Cross(Vector3.up,directions[family]);var seam=new float[(int)Width*2+1];for(int j=0;j<seam.Length;j++){var q=p+right*(j-Width);seam[j]=H(q.x,q.z)-p.y;}var modules=new GameObject[6];for(int h=0;h<2;h++)for(int bend=-1;bend<=1;bend++)modules[h*3+bend+1]=Module(family,bend,h==0?1:-1,p,seam);arms[family]=new AuthoredForestArm{name=family==0?"Восточный лес":"Западный лес",entrance=p,yaw=Quaternion.LookRotation(directions[family]).eulerAngles.y,modules=modules};}
  foreach(var f in forest.GetComponentsInChildren<MeshFilter>())CropMesh(f,f.GetComponent<MeshCollider>(),endpoints[0],directions[0],endpoints[1],directions[1],f.name);
  var collision=GameObject.Find("Forest solid collision - visible surface");int index=0;if(collision!=null)foreach(var c in collision.GetComponentsInChildren<MeshCollider>())CropMesh(null,c,endpoints[0],directions[0],endpoints[1],directions[1],"collision "+index++);
  var root=new GameObject("Authored forest road - streamed original model");var route=root.AddComponent<AuthoredForestRoute>();route.vehicle=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>().transform;route.arms=arms;route.Prepare();route.editorPreview=new GameObject("Authored road preview - replaced by streaming in Play");route.editorPreview.transform.SetParent(root.transform,false);for(int a=0;a<2;a++)for(int b=0;b<6;b++){var record=arms[a].records[b];var block=(GameObject)PrefabUtility.InstantiatePrefab(arms[a].modules[record.module]);block.transform.SetParent(route.editorPreview.transform,false);block.transform.SetPositionAndRotation(route.Position(a,b),route.Rotation(a,b));}
  AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return "Built 12 stitched module variants entirely from supplied forest meshes and original UV/material maps; original-map joins cropped only beyond both road endpoints; both directions stream to 10,000km. Active preview: 6 modules each direction. Native module lengths="+string.Join(",",arms[0].modules.Select(p=>p.GetComponent<AuthoredForestBlock>().length.ToString("F1")))+"m. Backup="+backup;
 }
}
